package com.astroshop.automation.support;

import com.fasterxml.jackson.databind.ObjectMapper;
import com.fasterxml.jackson.databind.node.ArrayNode;
import com.fasterxml.jackson.databind.node.ObjectNode;
import io.restassured.response.Response;

import static io.restassured.RestAssured.given;

/**
 * The frontend proxies flagd's config at /feature/api/{read,write} (confirmed by the demo
 * repo's own src/frontend/cypress/e2e/CheckoutPaymentFailure.cy.ts) — the same mechanism the
 * flagd-ui container uses, reused here rather than inventing a second way to reach flagd.
 */
public final class FlagdClient {

    private static final String READ_PATH = "/feature/api/read";
    private static final String WRITE_PATH = "/feature/api/write";

    /**
     * Live-verified (against the real docker-compose stack, in the original TypeScript version
     * of this suite): the flag-write endpoint returns before flagd/the target service has
     * actually applied the new value. A request fired immediately after a write can observe the
     * stale value — an isolated test toggling paymentFailure to 100% and checking out
     * immediately got a 200, not the expected 422, ~357ms end to end. 1s is an empirical
     * margin, not a documented flagd guarantee — see ../automation-strategy.md "Flakiness".
     */
    private static final long PROPAGATION_DELAY_MS = 1000;

    private static final ObjectMapper MAPPER = new ObjectMapper();

    private FlagdClient() {}

    public static void setFlag(String flagName, String defaultVariant) {
        ObjectNode config = readConfig();
        ObjectNode flag = flagNode(config, flagName);
        flag.put("defaultVariant", defaultVariant);
        write(config);
        sleepForPropagation();
    }

    /**
     * productCatalogFailure targets one product ID via a targeting rule instead of a plain
     * defaultVariant, so toggling it means flipping the rule's true-branch — matching how the
     * /feature UI itself edits this specific flag.
     */
    public static void setProductCatalogFailure(String variant) {
        ObjectNode config = readConfig();
        ObjectNode flag = flagNode(config, "productCatalogFailure");
        ArrayNode ifArray = (ArrayNode) flag.get("targeting").get("if");
        ifArray.set(1, variant);
        write(config);
        sleepForPropagation();
    }

    public static void resetFlag(String flagName) {
        setFlag(flagName, "off");
    }

    private static ObjectNode flagNode(ObjectNode config, String flagName) {
        ObjectNode flags = (ObjectNode) config.get("flags");
        ObjectNode flag = flags == null ? null : (ObjectNode) flags.get(flagName);
        if (flag == null) {
            throw new IllegalArgumentException(
                "Unknown flag \"" + flagName + "\" — check src/flagd/demo.flagd.json in the demo repo");
        }
        return flag;
    }

    private static ObjectNode readConfig() {
        Response res = given().baseUri(TestConfig.baseUrl()).get(READ_PATH);
        try {
            return (ObjectNode) MAPPER.readTree(res.getBody().asString());
        } catch (Exception e) {
            throw new IllegalStateException("Failed to parse flagd config from " + READ_PATH, e);
        }
    }

    private static void write(ObjectNode fullConfig) {
        ObjectNode payload = MAPPER.createObjectNode();
        payload.set("data", fullConfig);
        given().baseUri(TestConfig.baseUrl())
            .contentType("application/json")
            .body(payload.toString())
            .post(WRITE_PATH)
            .then();
    }

    private static void sleepForPropagation() {
        try {
            Thread.sleep(PROPAGATION_DELAY_MS);
        } catch (InterruptedException e) {
            Thread.currentThread().interrupt();
        }
    }
}

