package com.astroshop.automation.support;

import com.fasterxml.jackson.databind.ObjectMapper;
import com.fasterxml.jackson.databind.node.ObjectNode;

import java.time.Year;
import java.util.concurrent.ThreadLocalRandom;

/**
 * Real product IDs + names seeded by the demo's postgresql/init.sql — not synthetic values —
 * plus builders for request payloads shared across api/, contract/ and ui/ tests. No shared,
 * mutating fixtures: every test generates its own userId/session via uniqueUserId(), so tests
 * can run in any order, alone, or (data-wise) in parallel without colliding. Surefire is still
 * configured to run serially — see pom.xml — because flagd's config is a separate, truly
 * global, mutable resource that per-test data isolation can't fix.
 */
public final class TestData {

    private TestData() {}

    public static final String EXPLORASCOPE = "OLJCESPC7Z"; // the one productCatalogFailure targets
    public static final String SOLAR_SYSTEM_IMAGER = "0PUK6V6EV0";
    public static final String TRAVEL_TELESCOPE = "1YMWWN1N4O";
    public static final String BINOCULARS = "2ZYFJ3GM2N";
    public static final String REFRACTOR_TELESCOPE = "66VCHSJNUP";

    public static final String NONEXISTENT_PRODUCT_ID = "ZZZZZZZZZZ";

    private static final ObjectMapper MAPPER = new ObjectMapper();

    public static String uniqueUserId(String prefix) {
        return prefix + "-" + System.currentTimeMillis() + "-" + ThreadLocalRandom.current().nextInt(10_000);
    }

    public static ObjectNode validAddress() {
        ObjectNode address = MAPPER.createObjectNode();
