package com.astroshop.automation.support;

import java.io.IOException;
import java.io.UncheckedIOException;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.Path;
import java.nio.file.StandardOpenOption;
import java.time.Instant;

/**
 * In-house equivalent of the old Playwright suite's
 * {@code test.info().annotations.push({type: 'quality-risk', ...})}: surfaces a finding that's
 * worth a human's attention — a confirmed bug pinned as a regression guard, a suspicious value,
 * an undocumented behavior — without failing (or silently passing) the build on it.
 *
 * Appends to target/quality-risks.md (one line per finding, so a CI job can archive or post it)
 * and prints a clearly tagged line so it's visible in console/log output too. This is a
 * lightweight, in-house mechanism, not a replacement for real defect tracking — findings here
 * should get triaged into the team's actual ticket queue, not live only in this file.
 */
public final class QualityRisk {

    private static final Path REPORT_FILE = Path.of("target", "quality-risks.md");

    private QualityRisk() {}

    public static synchronized void flag(String testId, String description) {
        String line = String.format("- **%s** (%s): %s%n", testId, Instant.now(), description);
        System.out.println("[QUALITY-RISK] " + testId + ": " + description);
        try {
            Files.createDirectories(REPORT_FILE.getParent());
            Files.writeString(REPORT_FILE, line, StandardCharsets.UTF_8,
                StandardOpenOption.CREATE, StandardOpenOption.APPEND);
        } catch (IOException e) {
            throw new UncheckedIOException(e);
        }
    }
}

