package com.astroshop.automation.contract;

import java.util.Collections;
import java.util.List;

/** Outcome of one {@link ContractVerifier#verify} call: which contract, and every violation found. */
public final class ContractResult {

    private final String contractName;
    private final List<String> violations;

    ContractResult(String contractName, List<String> violations) {
        this.contractName = contractName;
        this.violations = Collections.unmodifiableList(violations);
    }

    public String contractName() {
        return contractName;
    }

    public List<String> violations() {
        return violations;
    }

    public boolean isSatisfied() {
        return violations.isEmpty();
    }

    /**
     * Fails with every violation listed, not just the first — a contract test that stops at the
     * first mismatch hides how many other fields also drifted, which is exactly the information
     * a human needs to judge "one field renamed" vs. "the whole response shape changed".
     */
    public void assertSatisfied() {
        if (isSatisfied()) {
            return;
        }
        StringBuilder message = new StringBuilder();
        message.append("Contract \"").append(contractName).append("\" violated (")
            .append(violations.size()).append(" issue(s)):\n");
        for (String violation : violations) {
            message.append("  - ").append(violation).append('\n');
        }
        throw new AssertionError(message.toString());
    }
}

