package com.astroshop.automation.contract;

import com.fasterxml.jackson.databind.JsonNode;
import com.fasterxml.jackson.databind.ObjectMapper;
import com.fasterxml.jackson.databind.node.MissingNode;

import java.io.IOException;
import java.io.InputStream;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.Iterator;
import java.util.List;
import java.util.regex.Pattern;

/**
 * In-house contract verifier: diffs a real API response against a checked-in expected-shape
 * fixture stored under {@code src/test/resources/contracts/expected/<name>.json}.
 *
 * <p>Why not a literal field-for-field JSON diff? Most of these responses contain real dynamic
 * data — generated order IDs, tracking IDs, prices that vary by currency, timestamps — that a
 * literal expected/actual comparison would need to special-case into meaninglessness or that
 * would make the "expected" fixture immediately stale. Instead, an expected-contract fixture is
 * itself a small JSON document written in a token DSL that describes the *shape* a field must
 * have, not its exact value:
 *
 * <ul>
 *   <li>{@code "$string"} — must be a JSON string (any value, including empty)</li>
 *   <li>{@code "$string:nonEmpty"} — a non-empty JSON string</li>
 *   <li>{@code "$string:pattern:REGEX"} — a string matching the given regex</li>
 *   <li>{@code "$number"} — any JSON number</li>
 *   <li>{@code "$number:positive"} / {@code "$number:nonNegative"} — a bounded JSON number</li>
 *   <li>{@code "$boolean"} — a JSON boolean</li>
 *   <li>{@code "$array"} / {@code "$array:nonEmpty"} / {@code "$array:minItems:N"} — array-level
 *       checks only (does not inspect elements)</li>
 *   <li>{@code "$enum:A|B|C"} — a string that must be one of the listed values</li>
 *   <li>{@code "$any"} — field must merely be present</li>
 *   <li>a literal value (no leading {@code $}) — the field must equal it exactly, useful for
 *       fixed things like an error {@code code}</li>
 *   <li>a nested object — recurses key by key</li>
 *   <li>an object containing the reserved key {@code "$eachItem"} — treats the corresponding
 *       actual field as an array of unknown length and applies the {@code $eachItem} shape to
 *       every element; {@code "$minItems"}/{@code "$maxItems"} (siblings of {@code $eachItem})
 *       bound the array's length</li>
 * </ul>
 *
 * <p>Design choice: any field present in the <b>actual</b> response but not mentioned in the
 * expected fixture is ignored, not flagged. This verifier checks that the contract's
 * obligations are met (every promised field is present and correctly shaped), not that the
 * response is exhaustively described — a service adding a new, additive field shouldn't break
 * every consumer's contract test. A missing key mentioned in the fixture, or a token mismatch
 * (wrong type, empty when required non-empty, wrong enum value), is always a violation.
 */
public final class ContractVerifier {

    private static final ObjectMapper MAPPER = new ObjectMapper();

    private ContractVerifier() {}

    public static ContractResult verify(String contractName, JsonNode actual) {
        JsonNode expected = loadExpected(contractName);
        List<String> violations = new ArrayList<>();
        walk("$", expected, actual == null ? MissingNode.getInstance() : actual, violations);
        return new ContractResult(contractName, violations);
    }

    public static ContractResult verify(String contractName, String actualJson) {
        try {
            return verify(contractName, MAPPER.readTree(actualJson));
        } catch (IOException e) {
            throw new IllegalArgumentException(
                "Actual response body is not valid JSON for contract \"" + contractName + "\": " + actualJson, e);
        }
    }

    private static JsonNode loadExpected(String contractName) {
        String resourcePath = "/contracts/expected/" + contractName + ".json";
        try (InputStream in = ContractVerifier.class.getResourceAsStream(resourcePath)) {
            if (in == null) {
                throw new IllegalArgumentException("No expected-contract fixture found at src/test/resources"
                    + resourcePath + " — add one before calling ContractVerifier.verify(\"" + contractName + "\", ...)");
            }
            return MAPPER.readTree(in);
        } catch (IOException e) {
            throw new IllegalStateException("Failed to read/parse src/test/resources" + resourcePath, e);
        }
    }

    private static void walk(String path, JsonNode expected, JsonNode actual, List<String> violations) {
        if (isEachItemWrapper(expected)) {
            verifyEachItem(path, expected, actual, violations);
            return;
        }
        if (expected.isObject()) {
            verifyObject(path, expected, actual, violations);
            return;
        }
        if (expected.isArray()) {
            verifyLiteralArray(path, expected, actual, violations);
            return;
        }
        if (expected.isTextual() && expected.asText().startsWith("$")) {
            applyToken(path, expected.asText(), actual, violations);
            return;
        }
        // A literal scalar (string that isn't a token, number, boolean, null) — exact match.
        if (actual.isMissingNode()) {
            violations.add(path + ": missing field (contract requires literal value " + expected + ")");
        } else if (!expected.equals(actual)) {
            violations.add(path + ": expected literal value " + expected + " but got " + describe(actual));
        }
    }

    private static boolean isEachItemWrapper(JsonNode expected) {
        return expected.isObject() && expected.has("$eachItem");
    }

    private static void verifyEachItem(String path, JsonNode expected, JsonNode actual, List<String> violations) {
        if (!actual.isArray()) {
            violations.add(path + ": expected an array (contract uses $eachItem), but actual was " + describe(actual));
            return;
        }
        if (expected.has("$minItems")) {
            int min = expected.get("$minItems").asInt();
            if (actual.size() < min) {
                violations.add(path + ": expected at least " + min + " item(s), got " + actual.size());
            }
        }
        if (expected.has("$maxItems")) {
            int max = expected.get("$maxItems").asInt();
            if (actual.size() > max) {
                violations.add(path + ": expected at most " + max + " item(s), got " + actual.size());
            }
        }
        JsonNode itemShape = expected.get("$eachItem");
        for (int i = 0; i < actual.size(); i++) {
            walk(path + "[" + i + "]", itemShape, actual.get(i), violations);
        }
    }

    private static void verifyObject(String path, JsonNode expected, JsonNode actual, List<String> violations) {
        if (!actual.isObject()) {
            violations.add(path + ": expected an object, but actual was " + describe(actual));
            return;
        }
        Iterator<String> fields = expected.fieldNames();
        while (fields.hasNext()) {
            String field = fields.next();
            JsonNode expectedChild = expected.get(field);
            JsonNode actualChild = actual.has(field) ? actual.get(field) : MissingNode.getInstance();
            walk(path + "." + field, expectedChild, actualChild, violations);
        }
    }

    /** Rarely used: a fixed-length, position-by-position expected array (e.g. tuple-like data). */
    private static void verifyLiteralArray(String path, JsonNode expected, JsonNode actual, List<String> violations) {
        if (!actual.isArray()) {
            violations.add(path + ": expected an array, but actual was " + describe(actual));
            return;
        }
        if (expected.size() != actual.size()) {
            violations.add(path + ": expected exactly " + expected.size() + " element(s), actual had " + actual.size());
        }
        int n = Math.min(expected.size(), actual.size());
        for (int i = 0; i < n; i++) {
            walk(path + "[" + i + "]", expected.get(i), actual.get(i), violations);
        }
    }

    private static void applyToken(String path, String token, JsonNode actual, List<String> violations) {
        if (actual.isMissingNode() || actual.isNull()) {
            violations.add(path + ": missing/null field (contract requires " + token + ")");
            return;
        }

        String[] parts = token.split(":", 3);
        String kind = parts[0];

        switch (kind) {
            case "$any" -> { /* presence alone (checked above) satisfies this token */ }
            case "$string" -> verifyString(path, parts, actual, violations);
            case "$number" -> verifyNumber(path, parts, actual, violations);
            case "$boolean" -> {
                if (!actual.isBoolean()) {
                    violations.add(path + ": expected a boolean, got " + describe(actual));
                }
            }
            case "$array" -> verifyArrayToken(path, parts, actual, violations);
            case "$enum" -> verifyEnum(path, parts, actual, violations);
            default -> violations.add(path + ": unrecognized contract token \"" + token
                + "\" — check the DSL documented on ContractVerifier");
        }
    }

    private static void verifyString(String path, String[] parts, JsonNode actual, List<String> violations) {
        if (!actual.isTextual()) {
            violations.add(path + ": expected a string, got " + describe(actual));
            return;
        }
        if (parts.length <= 1) {
            return;
        }
        switch (parts[1]) {
            case "nonEmpty" -> {
                if (actual.asText().isEmpty()) {
                    violations.add(path + ": expected a non-empty string");
                }
            }
            case "pattern" -> {
                String regex = parts.length > 2 ? parts[2] : "";
                if (!Pattern.matches(regex, actual.asText())) {
                    violations.add(path + ": string \"" + actual.asText() + "\" does not match pattern /" + regex + "/");
                }
            }
            default -> violations.add(path + ": unknown $string qualifier \"" + parts[1] + "\" in contract fixture");
        }
    }

    private static void verifyNumber(String path, String[] parts, JsonNode actual, List<String> violations) {
        if (!actual.isNumber()) {
            violations.add(path + ": expected a number, got " + describe(actual));
            return;
        }
        if (parts.length <= 1) {
            return;
        }
        double value = actual.asDouble();
        switch (parts[1]) {
            case "positive" -> {
                if (!(value > 0)) {
                    violations.add(path + ": expected a positive number, got " + value);
                }
            }
            case "nonNegative" -> {
                if (!(value >= 0)) {
                    violations.add(path + ": expected a non-negative number, got " + value);
                }
            }
            default -> violations.add(path + ": unknown $number qualifier \"" + parts[1] + "\" in contract fixture");
        }
    }

    private static void verifyArrayToken(String path, String[] parts, JsonNode actual, List<String> violations) {
        if (!actual.isArray()) {
            violations.add(path + ": expected an array, got " + describe(actual));
            return;
        }
        if (parts.length <= 1) {
            return;
        }
        int size = actual.size();
        switch (parts[1]) {
            case "nonEmpty" -> {
                if (size == 0) {
                    violations.add(path + ": expected a non-empty array");
                }
            }
            case "minItems" -> {
                int min = Integer.parseInt(parts[2]);
                if (size < min) {
                    violations.add(path + ": expected at least " + min + " item(s), got " + size);
                }
            }
            default -> violations.add(path + ": unknown $array qualifier \"" + parts[1] + "\" in contract fixture");
        }
    }

    private static void verifyEnum(String path, String[] parts, JsonNode actual, List<String> violations) {
        if (!actual.isTextual()) {
            violations.add(path + ": expected a string for enum check, got " + describe(actual));
            return;
        }
        List<String> allowed = Arrays.asList((parts.length > 1 ? parts[1] : "").split("\\|"));
        if (!allowed.contains(actual.asText())) {
            violations.add(path + ": value \"" + actual.asText() + "\" is not one of " + allowed);
        }
    }

    private static String describe(JsonNode node) {
        if (node == null || node.isMissingNode()) {
            return "<missing>";
        }
        if (node.isNull()) {
            return "null";
        }
        return node.getNodeType() + " (" + node + ")";
    }
}

