package com.astroshop.automation.api;

import com.astroshop.automation.support.ApiTestBase;
import com.astroshop.automation.support.FlagdClient;
import com.astroshop.automation.support.QualityRisk;
import com.astroshop.automation.support.TestData;
import io.restassured.response.Response;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;

import java.util.List;

import static io.restassured.RestAssured.given;
import static org.hamcrest.Matchers.emptyString;
import static org.hamcrest.Matchers.equalTo;
import static org.hamcrest.Matchers.not;
import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertNotNull;
import static org.junit.jupiter.api.Assertions.assertNull;
import static org.junit.jupiter.api.Assertions.assertTrue;

/**
 * Covers TC-CO-01..TC-CO-04 from test-cases/01-checkout-flow.md. TC-CO-05 (currency mismatch)
 * needs the currency service's actual conversion rate to assert against precisely — see
 * ../../../../../README.md "What's not automated, and why" for why that's deliberately left as
 * a manual/exploratory case for now.
 *
 * These tests assert business *behavior* (status codes, cart-clearing, error classification).
 * Response *shape* is asserted separately in contract/CheckoutContractTest against the fixtures
 * under src/test/resources/contracts/expected/ — see test-strategy.md §2 for why this repo
 * treats "integration" and "contract" as one merged pyramid layer even though they live in
 * separate test classes here for readability.
 */
class CheckoutApiTest extends ApiTestBase {

    @Test
    @DisplayName("TC-CO-01: placing an order with a valid cart clears the cart and returns a consistent order")
    void happyPathSingleItemClearsCart() {
        String userId = TestData.uniqueUserId("tc-co-01");

        given().contentType("application/json")
            .body(TestData.addToCartPayload(userId, TestData.SOLAR_SYSTEM_IMAGER, 2).toString())
            .post("/api/cart")
            .then().statusCode(200);

        given().queryParam("sessionId", userId).queryParam("currencyCode", "USD")
            .get("/api/cart")
            .then().statusCode(200)
            .body("items.size()", equalTo(1))
            .body("items[0].quantity", equalTo(2));

        Response checkoutRes = given().contentType("application/json")
            .queryParam("currencyCode", "USD")
            .body(TestData.checkoutPayload(userId).toString())
            .post("/api/checkout");

        checkoutRes.then().statusCode(200)
            .body("orderId", not(emptyString()))
            .body("shippingTrackingId", not(emptyString()))
            .body("items.size()", equalTo(1))
            .body("items[0].item.quantity", equalTo(2));

        // Server-side cart must be cleared after a successful order.
        given().queryParam("sessionId", userId).queryParam("currencyCode", "USD")
            .get("/api/cart")
            .then().statusCode(200)
            .body("items.size()", equalTo(0));
    }

    @Test
    @DisplayName("TC-CO-01 edge case: multiple distinct products all appear in the order, none dropped")
    void happyPathMultipleProductsNoneDropped() {
        String userId = TestData.uniqueUserId("tc-co-01b");

        given().contentType("application/json")
            .body(TestData.addToCartPayload(userId, TestData.SOLAR_SYSTEM_IMAGER, 1).toString())
            .post("/api/cart");
        given().contentType("application/json")
            .body(TestData.addToCartPayload(userId, TestData.TRAVEL_TELESCOPE, 3).toString())
            .post("/api/cart");

        Response checkoutRes = given().contentType("application/json")
            .queryParam("currencyCode", "USD")
            .body(TestData.checkoutPayload(userId).toString())
            .post("/api/checkout");

        checkoutRes.then().statusCode(200);
        List<String> productIds = checkoutRes.jsonPath().getList("items.item.productId", String.class);
        assertEquals(2, productIds.size());
        assertTrue(productIds.contains(TestData.SOLAR_SYSTEM_IMAGER));
        assertTrue(productIds.contains(TestData.TRAVEL_TELESCOPE));
    }

    @Test
    @DisplayName("TC-CO-02: a declined payment returns 422 PAYMENT_FAILED and preserves the cart")
    void paymentDeclinedPreservesCart() {
        FlagdClient.setFlag("paymentFailure", "100%");
        try {
            String userId = TestData.uniqueUserId("tc-co-02");
            given().contentType("application/json")
                .body(TestData.addToCartPayload(userId, TestData.SOLAR_SYSTEM_IMAGER, 1).toString())
                .post("/api/cart");

            given().contentType("application/json")
                .queryParam("currencyCode", "USD")
                .body(TestData.checkoutPayload(userId).toString())
                .post("/api/checkout")
                .then().statusCode(422)
                .body("code", equalTo("PAYMENT_FAILED"))
                .body("error", not(emptyString()));

            // A declined payment must not silently empty the cart — the customer should be able to retry.
            given().queryParam("sessionId", userId).get("/api/cart")
                .then().body("items.size()", equalTo(1));
        } finally {
            FlagdClient.resetFlag("paymentFailure");
        }
    }

    @Test
    @DisplayName("TC-CO-03 (adapted): a product-catalog failure during order-item enrichment "
        + "returns a generic 500, not PAYMENT_FAILED")
    void unrelatedDownstreamFailureIsNotMisclassifiedAsPaymentDecline() {
        // The literal TC-CO-03 case (100% cartFailure during checkout) is a manual case — see
        // README.md "What's not automated, and why". checkout's actual first downstream
        // dependency in the code is ProductCatalogService, which productCatalogFailure targets
        // deterministically, so that's the automated proxy for "a downstream call inside
        // checkout fails cleanly and isn't misclassified as a payment decline".
        FlagdClient.setProductCatalogFailure("on");
        try {
            String userId = TestData.uniqueUserId("tc-co-03");
            given().contentType("application/json")
                .body(TestData.addToCartPayload(userId, TestData.EXPLORASCOPE, 1).toString())
                .post("/api/cart");

            Response res = given().contentType("application/json")
                .queryParam("currencyCode", "USD")
                .body(TestData.checkoutPayload(userId).toString())
                .post("/api/checkout");

            res.then().statusCode(500);
            assertNull(res.jsonPath().get("code"));
            assertNotNull(res.jsonPath().getString("error"));
        } finally {
            FlagdClient.setProductCatalogFailure("off");
        }
    }

    @Test
    @DisplayName("TC-CO-04: checking out with an empty cart 500s with a generic error, not a graceful 4xx (bug)")
    void emptyCartCheckoutPinsConfirmedBug() {
        // This was written as an open ambiguity ("what SHOULD happen?") and resolved by running
        // it live: checking out an empty cart returns a bare 500
        // {"error":"Failed to place order."} — an unhandled internal error, not a graceful 4xx
        // validation response. That's a real quality bug (a customer double-tapping through an
        // emptied cart gets a generic server-error page instead of "your cart is empty"), so
        // this test pins the CURRENT (bad) behavior as a regression guard — a fix should change
        // this test's expectation to a 4xx, not the other way around.
        String userId = TestData.uniqueUserId("tc-co-04");
        // Deliberately never add anything to the cart for this userId.

        given().contentType("application/json")
            .queryParam("currencyCode", "USD")
            .body(TestData.checkoutPayload(userId).toString())
            .post("/api/checkout")
            .then().statusCode(500);

        QualityRisk.flag("TC-CO-04",
            "CONFIRMED: empty-cart checkout returns an unhandled 500 instead of a 4xx validation error. "
                + "See test-cases/01-checkout-flow.md TC-CO-04.");
    }
}

