 * cartFailure %) is scripted at 100% only, not the full 10-90% sweep — see README.md for why a
 * percentage-based flag test is inherently a soft assertion below 100%.
 */
class CartApiTest extends ApiTestBase {

    @Test
    @DisplayName("TC-CT-01: adding the same product twice accumulates quantity into one line item")
    void addingSameProductTwiceAccumulatesQuantity() {
        String userId = TestData.uniqueUserId("tc-ct-01");

        given().contentType("application/json")
            .body(TestData.addToCartPayload(userId, TestData.SOLAR_SYSTEM_IMAGER, 1).toString())
            .post("/api/cart");

        // This assertion encodes our inferred expectation (accumulate, not overwrite) — the
        // proto doesn't document this, so a failure here is a signal to confirm intended
        // behavior with the cart service owner, not necessarily "our test is wrong".
        given().contentType("application/json")
            .body(TestData.addToCartPayload(userId, TestData.SOLAR_SYSTEM_IMAGER, 2).toString())
            .post("/api/cart")
            .then().statusCode(200)
            .body("items.size()", equalTo(1))
            .body("items[0].quantity", equalTo(3));

        given().queryParam("sessionId", userId).get("/api/cart")
            .then().body("items[0].quantity", equalTo(3));
    }

    @Test
    @DisplayName("TC-CT-02: emptying the cart returns 204 and a subsequent read is empty, not stale")
    void emptyingCartThenReadingIsEmptyNotStale() {
        String userId = TestData.uniqueUserId("tc-ct-02");

        given().contentType("application/json")
            .body(TestData.addToCartPayload(userId, TestData.TRAVEL_TELESCOPE, 1).toString())
            .post("/api/cart");

        given().contentType("application/json")
            .body(TestData.userIdPayload(userId).toString())
            .delete("/api/cart")
            .then().statusCode(204);

        given().queryParam("sessionId", userId).get("/api/cart")
            .then().body("items.size()", equalTo(0));
    }

    @Test
    @DisplayName("TC-CT-02 edge case: deleting a cart that was never created is idempotent, not a 5xx")
    void deletingNeverCreatedCartIsIdempotent() {
        String userId = TestData.uniqueUserId("tc-ct-02-never-existed");
        given().contentType("application/json")
            .body(TestData.userIdPayload(userId).toString())
            .delete("/api/cart")
            .then().statusCode(lessThan(500));
    }

    @Test
    @DisplayName("TC-CT-03 (corrected): cartFailure only affects EmptyCart, not GetCart/AddItem")
    void cartFailureDoesNotAffectReadsOrAdds() {
        // REAL FINDING from running this against the live docker-compose stack (see
        // src/cart/src/services/CartService.cs in the demo repo): cartFailure is checked ONLY
        // inside EmptyCart, not AddItem or GetCart — so a "cart service failure" fault
        // injection does NOT make cart reads fail at all. Corrected from an earlier version
        // that targeted GetCart and failed against the live app. See
        // test-cases/02-cart-flow.md TC-CT-04.
        FlagdClient.setFlag("cartFailure", "100%");
        try {
            String userId = TestData.uniqueUserId("tc-ct-03-read");
            given().contentType("application/json")
                .body(TestData.addToCartPayload(userId, TestData.SOLAR_SYSTEM_IMAGER, 1).toString())
                .post("/api/cart");

            given().queryParam("sessionId", userId).get("/api/cart")
                .then().statusCode(200); // documents the real (surprising) behavior, not a guess
        } finally {
            FlagdClient.resetFlag("cartFailure");
        }
    }

    @Test
    @DisplayName("TC-CT-03: under 100% cartFailure, EmptyCart fails with a clean 5xx (not a silent success)")
    void cartFailureBreaksEmptyCart() {
        FlagdClient.setFlag("cartFailure", "100%");
        try {
            String userId = TestData.uniqueUserId("tc-ct-03-delete");
            given().contentType("application/json")
                .body(TestData.addToCartPayload(userId, TestData.SOLAR_SYSTEM_IMAGER, 1).toString())
                .post("/api/cart");

            // cartFailure routes EmptyCart to a hardcoded unreachable store ("badhost:1234" in
            // Program.cs) instead of returning a documented error — it fails, but as an
            // unhandled infra-level exception, not an intentional application error. Confirmed
            // live: 500 after ~2s (the connection attempt failing), not a graceful decline.
            given().contentType("application/json")
                .body(TestData.userIdPayload(userId).toString())
                .delete("/api/cart")
                .then().statusCode(greaterThanOrEqualTo(500));
        } finally {
            FlagdClient.resetFlag("cartFailure");
        }
    }
}

