package com.astroshop.automation.api;

import com.astroshop.automation.support.ApiTestBase;
import com.astroshop.automation.support.FlagdClient;
import com.astroshop.automation.support.QualityRisk;
import com.astroshop.automation.support.TestData;
import io.restassured.response.Response;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;

import java.util.List;

import static io.restassured.RestAssured.given;
import static org.hamcrest.Matchers.greaterThanOrEqualTo;
import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertTrue;

/**
 * Covers TC-PC-01, TC-PC-02 from test-cases/03-product-catalog-currency.md, plus the
 * nonexistent-product regression guard. TC-PC-03 (search edge cases) has no REST BFF route to
 * exercise at all — see ProductCatalogGrpcTest, which covers it directly over gRPC instead.
 */
class ProductCatalogApiTest extends ApiTestBase {

    @Test
    @DisplayName("TC-PC-01: the same product returns consistent, correctly-shaped prices across currencies")
    void currencyConsistencyAcrossCurrencies() {
        Response usd = given().queryParam("currencyCode", "USD").get("/api/products/" + TestData.SOLAR_SYSTEM_IMAGER);
        Response eur = given().queryParam("currencyCode", "EUR").get("/api/products/" + TestData.SOLAR_SYSTEM_IMAGER);
        Response jpy = given().queryParam("currencyCode", "JPY").get("/api/products/" + TestData.SOLAR_SYSTEM_IMAGER);

        assertEquals("USD", usd.jsonPath().getString("priceUsd.currencyCode"));
        assertEquals("EUR", eur.jsonPath().getString("priceUsd.currencyCode"));
        assertEquals("JPY", jpy.jsonPath().getString("priceUsd.currencyCode"));

        // JPY has no minor unit — flag (don't hard-fail the whole suite on this, since we don't
        // know the service's exact rounding convention) if nanos is non-zero.
        int jpyNanos = jpy.jsonPath().getInt("priceUsd.nanos");
        if (jpyNanos != 0) {
            QualityRisk.flag("TC-PC-01",
                "JPY conversion for " + TestData.SOLAR_SYSTEM_IMAGER + " returned a non-zero nanos value ("
                    + jpyNanos + ") — JPY is zero-decimal, confirm rounding behavior with engineering.");
        }

        // Sanity bound: converted values should be in a plausible range of the USD price, not
        // zero and not absurdly large — catches a badly-inverted conversion rate.
        long eurUnits = eur.jsonPath().getLong("priceUsd.units");
        long jpyUnits = jpy.jsonPath().getLong("priceUsd.units");
        long usdUnits = usd.jsonPath().getLong("priceUsd.units");
        assertTrue(eurUnits > 0);
        assertTrue(jpyUnits > usdUnits); // JPY units are numerically larger for an equivalent value
    }

    @Test
    @DisplayName("TC-PC-02: failure targets only the flagged product, not the whole catalog")
    void targetedFailureDoesNotAffectOtherProducts() {
        FlagdClient.setProductCatalogFailure("on");
        try {
            given().get("/api/products/" + TestData.EXPLORASCOPE)
                .then().statusCode(greaterThanOrEqualTo(500));

            given().get("/api/products/" + TestData.SOLAR_SYSTEM_IMAGER)
                .then().statusCode(200);
        } finally {
            FlagdClient.setProductCatalogFailure("off");
        }
    }

    @Test
    @DisplayName("TC-PC-02 follow-up: list vs. detail behavior for the failing product must be consistent")
    void listVsDetailConsistencyUnderFailure() {
        FlagdClient.setProductCatalogFailure("on");
        try {
            Response list = given().get("/api/products");
            Response detail = given().get("/api/products/" + TestData.EXPLORASCOPE);

            boolean listOk = list.getStatusCode() == 200;
            boolean listIncludesFailingProduct = listOk
                && list.jsonPath().getList("id", String.class).contains(TestData.EXPLORASCOPE);

            if (listIncludesFailingProduct && detail.getStatusCode() >= 500) {
                QualityRisk.flag("TC-PC-02",
                    "Product list still includes the flagged product, but its detail page 500s — "
                        + "a broken-link experience under this fault condition.");
            }
        } finally {
            FlagdClient.setProductCatalogFailure("off");
        }
    }

    @Test
    @DisplayName("a nonexistent product ID returns an unhandled 500, not the 404 the backend actually signals (bug)")
    void nonexistentProductReturnsUnhandled500() {
        // REAL FINDING from the live app: product-catalog's GetProduct (main.go) correctly
        // returns a gRPC codes.NotFound for a missing ID, but the frontend BFF route
        // (pages/api/products/[productId]/index.ts) has NO error handling around the gRPC
        // call — it awaits the call with no try/catch, so any rejection (including a
        // well-formed NotFound) becomes an unhandled promise rejection and Next.js's default
        // 500. The backend does the right thing; the BFF throws it away. Pinning the current
        // (bad) behavior as a regression guard, same as TC-CO-04.
        given().get("/api/products/" + TestData.NONEXISTENT_PRODUCT_ID)
            .then().statusCode(500);

        QualityRisk.flag("TC-PC-nonexistent-product",
            "CONFIRMED: product-catalog correctly returns gRPC NotFound for a missing product, but the "
                + "frontend BFF route has no error handling and turns it into a generic 500. Fix belongs "
                + "in pages/api/products/[productId]/index.ts.");
    }
}

