package com.astroshop.automation.api;

import com.astroshop.automation.support.TestData;
import io.grpc.ManagedChannel;
import io.grpc.ManagedChannelBuilder;
import oteldemo.Demo.Product;
import oteldemo.Demo.SearchProductsRequest;
import oteldemo.Demo.SearchProductsResponse;
import oteldemo.ProductCatalogServiceGrpc;
import oteldemo.ProductCatalogServiceGrpc.ProductCatalogServiceBlockingStub;
import org.junit.jupiter.api.AfterAll;
import org.junit.jupiter.api.Assumptions;
import org.junit.jupiter.api.BeforeAll;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;

import java.util.List;
import java.util.concurrent.TimeUnit;

import static org.junit.jupiter.api.Assertions.assertDoesNotThrow;
import static org.junit.jupiter.api.Assertions.assertTrue;

/**
 * TC-PC-03 (search edge cases) — the only test in this suite that talks gRPC directly, because
 * SearchProducts has no REST BFF equivalent. Confirmed by reading
 * src/frontend/pages/api/products/index.ts and .../[productId]/index.ts in the demo repo: only
 * GET (list, detail) are wired up; there's no query-param pass-through to a search endpoint
 * anywhere in the REST BFF, even though SearchProducts exists in the proto and the service
 * implements it. Automated at the gRPC layer instead of skipping it or faking REST coverage
 * that doesn't exist.
 *
 * <p>The message/stub classes ({@code oteldemo.Demo.*}, {@code ProductCatalogServiceGrpc}) are
 * generated at build time straight from the demo app's own {@code pb/demo.proto} by the
 * protobuf-maven-plugin (see pom.xml) — not hand-written, so they can't silently drift from the
 * real contract.
 *
 * <p>Requires {@code PRODUCT_CATALOG_GRPC_ADDR} to be set to the docker-compose-published
 * host:port for product-catalog's 3550 (its host port isn't fixed in compose.yaml), e.g.:
 * <pre>
 *   export PRODUCT_CATALOG_GRPC_ADDR=$(docker compose -f ../opentelemetry-demo/compose.yaml \
 *     port product-catalog 3550 | sed 's/0.0.0.0/localhost/')
 * </pre>
 * Skipped (not failed) when the variable isn't set.
 */
class ProductCatalogGrpcTest {

    private static ManagedChannel channel;
    private static ProductCatalogServiceBlockingStub stub;

    @BeforeAll
    static void connect() {
        String addr = System.getenv("PRODUCT_CATALOG_GRPC_ADDR");
        Assumptions.assumeTrue(addr != null && !addr.isBlank(),
            "Set PRODUCT_CATALOG_GRPC_ADDR (see class Javadoc) to run this against a live docker-compose stack.");

        String[] hostPort = addr.split(":");
        channel = ManagedChannelBuilder.forAddress(hostPort[0], Integer.parseInt(hostPort[1]))
            .usePlaintext()
            .build();
        stub = ProductCatalogServiceGrpc.newBlockingStub(channel);
    }

    @AfterAll
    static void disconnect() throws InterruptedException {
        if (channel != null) {
            channel.shutdownNow().awaitTermination(5, TimeUnit.SECONDS);
        }
    }

    @Test
    @DisplayName("no-match query returns an empty result set, not an error")
    void noMatchQueryReturnsEmptyResults() {
        SearchProductsResponse res = stub.searchProducts(
            SearchProductsRequest.newBuilder().setQuery("zzz-nonexistent-zzz").build());
        assertTrue(res.getResultsList().isEmpty());
    }

    @Test
    @DisplayName("empty query does not throw")
    void emptyQueryDoesNotThrow() {
        assertDoesNotThrow(() -> stub.searchProducts(SearchProductsRequest.newBuilder().setQuery("").build()));
    }

    @Test
    @DisplayName("injection-shaped and very long queries are treated as literal strings, not errors")
    void injectionAndLongQueriesDoNotThrow() {
        assertDoesNotThrow(() -> stub.searchProducts(
            SearchProductsRequest.newBuilder().setQuery("' OR 1=1 --").build()));
        assertDoesNotThrow(() -> stub.searchProducts(
            SearchProductsRequest.newBuilder().setQuery("a".repeat(10_000)).build()));
    }

    @Test
    @DisplayName("a real product name substring returns that product")
    void realProductNameSubstringMatches() {
        // Cross-check: search should find a product we know exists by ID via a name fragment
        // ("Solar System Color Imager" per postgresql/init.sql).
        SearchProductsResponse res = stub.searchProducts(
            SearchProductsRequest.newBuilder().setQuery("Solar System").build());
        List<String> ids = res.getResultsList().stream().map(Product::getId).toList();
        assertTrue(ids.contains(TestData.SOLAR_SYSTEM_IMAGER));
    }
}

