package com.astroshop.automation.contract;

import com.astroshop.automation.support.ApiTestBase;
import com.astroshop.automation.support.FlagdClient;
import com.astroshop.automation.support.TestData;
import io.restassured.response.Response;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;

import static io.restassured.RestAssured.given;

/**
 * Dedicated contract-layer checks for the checkout endpoints: does the response still have the
 * shape callers (the frontend confirmation page, any future consumer) actually rely on?
 * Distinct from api/CheckoutApiTest, which asserts business *behavior* — these assert response
 * *shape* against a checked-in fixture (src/test/resources/contracts/expected/), independent of
 * the dynamic values (order IDs, prices) any single run produces. See ContractVerifier for the
 * verification mechanism and its token DSL.
 */
class CheckoutContractTest extends ApiTestBase {

    @Test
    @DisplayName("POST /api/checkout success response matches the checked-in OrderResult contract")
    void checkoutSuccessMatchesContract() {
        String userId = TestData.uniqueUserId("contract-checkout-ok");
        given().contentType("application/json")
            .body(TestData.addToCartPayload(userId, TestData.SOLAR_SYSTEM_IMAGER, 1).toString())
            .post("/api/cart");

        Response res = given().contentType("application/json")
            .queryParam("currencyCode", "USD")
            .body(TestData.checkoutPayload(userId).toString())
            .post("/api/checkout");

        res.then().statusCode(200);
        ContractVerifier.verify("checkout-order-result", res.getBody().asString()).assertSatisfied();
    }

    @Test
    @DisplayName("POST /api/checkout payment-declined error response matches the checked-in error contract")
    void checkoutPaymentDeclinedMatchesContract() {
        FlagdClient.setFlag("paymentFailure", "100%");
        try {
            String userId = TestData.uniqueUserId("contract-checkout-declined");
            given().contentType("application/json")
                .body(TestData.addToCartPayload(userId, TestData.SOLAR_SYSTEM_IMAGER, 1).toString())
                .post("/api/cart");

            Response res = given().contentType("application/json")
                .queryParam("currencyCode", "USD")
                .body(TestData.checkoutPayload(userId).toString())
                .post("/api/checkout");

            res.then().statusCode(422);
            ContractVerifier.verify("checkout-payment-declined-error", res.getBody().asString()).assertSatisfied();
        } finally {
            FlagdClient.resetFlag("paymentFailure");
        }
    }
}

