package com.astroshop.automation.contract;

import com.astroshop.automation.support.ApiTestBase;
import com.astroshop.automation.support.TestData;
import io.restassured.response.Response;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;

import static io.restassured.RestAssured.given;

/**
 * Contract-layer checks for /api/cart. GET and POST return genuinely different shapes — GET
 * enriches each line item with the full product (name, price) for display, POST returns the raw
 * gRPC Cart with just productId/quantity — so each gets its own fixture rather than pretending
 * they're the same contract.
 */
class CartContractTest extends ApiTestBase {

    @Test
    @DisplayName("POST /api/cart response matches the raw (unenriched) Cart contract")
    void addToCartMatchesRawContract() {
        String userId = TestData.uniqueUserId("contract-cart-post");
        Response res = given().contentType("application/json")
            .body(TestData.addToCartPayload(userId, TestData.SOLAR_SYSTEM_IMAGER, 1).toString())
            .post("/api/cart");

        res.then().statusCode(200);
        ContractVerifier.verify("cart-raw", res.getBody().asString()).assertSatisfied();
    }

    @Test
    @DisplayName("GET /api/cart response matches the product-enriched Cart contract")
    void getCartMatchesEnrichedContract() {
        String userId = TestData.uniqueUserId("contract-cart-get");
        given().contentType("application/json")
            .body(TestData.addToCartPayload(userId, TestData.SOLAR_SYSTEM_IMAGER, 1).toString())
            .post("/api/cart");

        Response res = given().queryParam("sessionId", userId).queryParam("currencyCode", "USD").get("/api/cart");

        res.then().statusCode(200);
        ContractVerifier.verify("cart-enriched", res.getBody().asString()).assertSatisfied();
    }
}

