package com.astroshop.automation.ui;

import com.astroshop.automation.support.TestConfig;
import com.microsoft.playwright.Browser;
import com.microsoft.playwright.BrowserContext;
import com.microsoft.playwright.BrowserType;
import com.microsoft.playwright.Page;
import com.microsoft.playwright.Playwright;
import org.junit.jupiter.api.AfterAll;
import org.junit.jupiter.api.AfterEach;
import org.junit.jupiter.api.BeforeAll;
import org.junit.jupiter.api.BeforeEach;

/**
 * Shared Playwright lifecycle for every UI test: one browser per test class, a fresh
 * context+page per test method so tests never share cookies/localStorage/session state with
 * each other. Chromium only, matching the original suite's scope (see automation-strategy.md —
 * no evidence of browser-specific bugs in this stack to justify a cross-browser matrix yet).
 *
 * Set HEADED=true to watch the browser while developing locally; CI and the default run stay
 * headless.
 */
public abstract class PlaywrightTestBase {

    private static Playwright playwright;
    private static Browser browser;

    protected BrowserContext context;
    protected Page page;

    @BeforeAll
    static void launchBrowser() {
        playwright = Playwright.create();
        boolean headed = "true".equalsIgnoreCase(System.getenv("HEADED"));
        browser = playwright.chromium().launch(new BrowserType.LaunchOptions().setHeadless(!headed));
    }

    @AfterAll
    static void closeBrowser() {
        if (browser != null) {
            browser.close();
        }
        if (playwright != null) {
            playwright.close();
        }
    }

    @BeforeEach
    void newContext() {
        context = browser.newContext(new Browser.NewContextOptions().setBaseURL(TestConfig.baseUrl()));
        page = context.newPage();
        page.setDefaultTimeout(15_000);
    }

    @AfterEach
    void closeContext() {
        if (context != null) {
            context.close();
        }
    }
}

