 * One deliberately small UI E2E test: browse -&gt; add to cart -&gt; checkout. This exists to
 * verify the layers are actually wired together through the browser (routing, client-side
 * state, real DOM). It does NOT re-verify business logic already covered at the API layer in
 * api/ — see automation-strategy.md for why E2E stays intentionally thin here.
 *
 * Complementary to (not a replacement for) the demo repo's own
 * src/frontend/cypress/e2e/Checkout.cy.ts, which already covers this golden path in Cypress;
 * this is the Playwright equivalent so the whole suite (UI + API + contract) runs from one
 * framework and one command. Selectors below are the app's own {@code data-cy} hooks
 * (src/frontend/utils/enums/CypressFields.ts), read directly from source rather than guessed.
 *
 * <p>REAL FINDINGS carried over from the original TypeScript version of this test, which was
 * run live against a docker-compose stack:
 * <ol>
 *   <li>{@code CheckoutForm}'s visible field labels ("E-mail Address", "Street Address", etc.)
 *   are plain {@code <p>} tags, not real {@code <label for=...>} elements — an
 *   accessible-name-based lookup (Playwright's {@code getByLabel}) fails against them entirely,
 *   because they carry no accessible-name association to their input. A minor a11y gap worth
 *   flagging to engineering (a screen reader user hits the same disconnect); moot for this test
 *   because the form ships pre-filled with valid sample data, so the golden path submits as-is
 *   without needing to address any field by label.</li>
 *   <li>{@code CypressFields.CheckoutItem} / {@code data-cy="checkout-item"} is DEAD in this
 *   flow: it's set on {@code components/CheckoutItem/CheckoutItem.tsx}, but the real
 *   order-confirmation page ({@code pages/cart/checkout/[orderId]/index.tsx}) renders its own
 *   inline markup instead and carries no {@code data-cy} hooks at all. This test asserts on
 *   real rendered content (the confirmation heading + the actual product name) instead of that
 *   dead hook.</li>
 * </ol>
 */
class GoldenPathTest extends PlaywrightTestBase {

    @Test
    @DisplayName("browse, add a product to the cart, and complete checkout")
    void browseAddToCartAndCompleteCheckout() {
        page.navigate("/");
        assertThat(page.locator("[data-cy=home-page]")).isVisible();

        // data-cy="product-name" only exists on the product detail page
        // (pages/product/[productId]), not on the homepage card — grab it after navigating.
        page.locator("[data-cy=product-card]").first().click();
        page.waitForURL(Pattern.compile(".*/product/.*"));
        Locator productNameLocator = page.locator("[data-cy=product-name]");
        assertThat(productNameLocator).isVisible();
        String productName = productNameLocator.textContent().trim();
        page.locator("[data-cy=product-add-to-cart]").click();

        // Adding an item auto-navigates to /cart (confirmed in the app's own Cypress suite).
        page.waitForURL(Pattern.compile(".*/cart$"));
        assertThat(page.locator("[data-cy=cart-item-count]")).containsText("1");

        // Checkout form is pre-filled with valid sample data — submit as-is.
        page.locator("[data-cy=checkout-place-order]").click();

        page.waitForURL(Pattern.compile(".*/checkout.*"));
        assertThat(page.getByRole(AriaRole.HEADING, new Page.GetByRoleOptions().setName("Your order is complete!")))
            .isVisible();
        assertThat(page.getByText("Order ID:")).isVisible();
        assertThat(page.getByText(productName)).isVisible();
    }
}

