import path from 'path';
import * as grpc from '@grpc/grpc-js';
import * as protoLoader from '@grpc/proto-loader';

/**
 * The proto is vendored into automation/protos/ (copied from opentelemetry-demo/pb/demo.proto,
 * upstream commit e297a3be) so this suite is self-contained: it does not depend on where, or
 * whether, the demo repo is cloned. Running `npm test` without the demo clone present used to
 * throw at test-collection time and abort the whole run with "0 tests in 0 files", because
 * the gRPC spec built its client while Playwright was still discovering tests.
 *
 * Refresh with: cp opentelemetry-demo/pb/demo.proto automation/protos/demo.proto
 */
const PROTO_PATH = path.resolve(__dirname, '../protos/demo.proto');

/**
 * product-catalog's gRPC port isn't fixed on the host — compose.yaml publishes it with
 * short-syntax `ports: ["${PRODUCT_CATALOG_PORT}"]`, which Docker maps to a random host
 * port each `docker compose up`. Resolve it once via:
 *   docker compose port product-catalog 3550
 * and pass the result as PRODUCT_CATALOG_GRPC_ADDR, or run tests from inside the compose
 * network where the fixed internal address (product-catalog:3550) works directly.
 */
export const PRODUCT_CATALOG_ADDR = process.env.PRODUCT_CATALOG_GRPC_ADDR;

export function productCatalogClient(address: string = PRODUCT_CATALOG_ADDR || 'localhost:3550') {
  const packageDef = protoLoader.loadSync(PROTO_PATH, {
    keepCase: false,
    longs: String,
    enums: String,
    defaults: true,
    oneofs: true,
  });
  const proto = grpc.loadPackageDefinition(packageDef) as any;
  return new proto.oteldemo.ProductCatalogService(address, grpc.credentials.createInsecure());
}

content.text:
`automation/fixtures/grpc.ts` builds a raw gRPC client so one specific test can talk **directly** to the `product-catalog` service, bypassing the frontend's REST BFF entirely. Here's why that's needed and what each part does.

**Why this file exists at all**

The frontend's REST API (`/api/products`, `/api/products/{id}`) never exposes product *search* — only listing and lookup by ID. But `product-catalog` does implement search over gRPC (`SearchProducts`, per `demo.proto`). Since there's no REST route to hit, the only way to test search at all is to speak gRPC directly to the service, which is what this fixture sets up for `product-catalog.grpc.spec.ts` (covering TC-PC-03).

**Line by line**

```ts
import * as grpc from '@grpc/grpc-js';
import * as protoLoader from '@grpc/proto-loader';
```
`@grpc/grpc-js` is Node's gRPC client library. `@grpc/proto-loader` lets you load a `.proto` file *at runtime* and get a usable client class from it, instead of needing a build-time codegen step (like `protoc`) the way a statically-typed language usually would.

```ts
const PROTO_PATH = path.resolve(__dirname, '../protos/demo.proto');
```
Points at a **vendored copy** of the proto file, committed inside `automation/protos/`, rather than reading it from the `opentelemetry-demo/` clone. Per the comment, this used to read from the demo clone directly, and that was a real bug: if the clone wasn't present, this file threw *while Playwright was still discovering tests*, which aborted the entire `npm test` run with "0 tests in 0 files" — even for tests that had nothing to do with gRPC. Vendoring the proto makes this suite self-contained.

```ts
export const PRODUCT_CATALOG_ADDR = process.env.PRODUCT_CATALOG_GRPC_ADDR;
```
`product-catalog`'s gRPC port (3550 inside the container) gets published to a **random** host port by `docker compose up`, unlike the other services. So there's no fixed `localhost:PORT` to hard-code — it has to be resolved per-run (`docker compose port product-catalog 3550`) and passed in via this env var.

```ts
export function productCatalogClient(address: string = PRODUCT_CATALOG_ADDR || 'localhost:3550') {
  const packageDef = protoLoader.loadSync(PROTO_PATH, {
    keepCase: false,   // proto's snake_case fields → camelCase in JS, matching the app's own convention
    longs: String,     // int64 fields come back as strings, not JS numbers — avoids silent precision loss
    enums: String,     // enum values come back as their name ("USD"), not a numeric index
    defaults: true,    // unset optional fields get their zero-value instead of `undefined`
    oneofs: true,      // a `oneof` group gets a virtual field saying which member was actually set
  });
  const proto = grpc.loadPackageDefinition(packageDef) as any;
  return new proto.oteldemo.ProductCatalogService(address, grpc.credentials.createInsecure());
}
```
This is a **factory function**, not a client built at module-import time — that's deliberate, for the same reason the proto got vendored: building the client eagerly (as an earlier version did) meant it could throw before anything even decided whether the gRPC test should run. Now it's only ever constructed inside the test itself, which is wrapped in a `test.skip(...)` guarded by whether `PRODUCT_CATALOG_GRPC_ADDR` is set — so an unconfigured environment just skips cleanly instead of crashing.

`proto.oteldemo.ProductCatalogService` — `oteldemo` is the package name declared in `demo.proto`, `ProductCatalogService` is the service name; loading it this way gives you a real client stub with a `SearchProducts` method callable over the wire. `grpc.credentials.createInsecure()` matches how the service actually runs internally — plaintext, no TLS.

**How it's actually used**

`product-catalog.grpc.spec.ts` calls `productCatalogClient()` to get a stub, then calls `client.SearchProducts({ query }, callback)` — note this is callback-based, not Promise-based (that's just how `@grpc/grpc-js` client stubs work by default), so the spec wraps each call in a small `new Promise((resolve, reject) => ...)` to `await` it like any other test.

